from pynwb import NWBHDF5IO
import numpy as np

for fpath in ['/app/data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb',
              '/app/data/sub-m3/sub-m3_ses-01_behavior+ophys.nwb']:
    print(f"\n=== {fpath.split('/')[-1]} ===")
    with NWBHDF5IO(fpath, 'r') as io:
        nwb = io.read()
        bts = nwb.processing['behavior']['BehavioralTimeSeries']
        print("Behavioral keys:", sorted(bts.time_series.keys()))

        for key in sorted(bts.time_series.keys()):
            ts_obj = bts.time_series[key]
            data = ts_obj.data[:]
            print(f"  {key}: shape={data.shape}, dtype={data.dtype}", end="")
            if hasattr(ts_obj, 'timestamps') and ts_obj.timestamps is not None:
                print(f", timestamps shape={ts_obj.timestamps.shape}", end="")
            if len(data.shape) == 1 and data.shape[0] < 200:
                uvals = np.unique(data)
                if len(uvals) <= 20:
                    print(f", unique={uvals}", end="")
                else:
                    print(f", range=[{np.min(data):.2f}, {np.max(data):.2f}]", end="")
            elif len(data.shape) == 1:
                uvals = np.unique(data)
                if len(uvals) <= 20:
                    print(f", unique={uvals}", end="")
                else:
                    print(f", range=[{np.min(data):.2f}, {np.max(data):.2f}]", end="")
            print()
